def backfill_legacy_work():
    """Never redispatch an unconfirmed invocation from the previous coordinator."""
    from datetime import datetime, timezone
    from uuid import uuid4
    conn = op.get_bind()
    metadata = sa.MetaData()
    metadata.reflect(conn, only=['evaluation_runs', 'trials', 'case_executions', 'grading_batches', 'work_items', 'audit_events'])
    runs, trials, executions, batches, items, audits = [metadata.tables[n] for n in
        ['evaluation_runs', 'trials', 'case_executions', 'grading_batches', 'work_items', 'audit_events']]
    active = list(conn.execute(sa.select(runs).where(runs.c.status.in_(['pending', 'queued', 'running', 'evaluating', 'cancelling']))).mappings())
    for run in active:
        unresolved = False
        for execution in conn.execute(sa.select(executions).join(trials, executions.c.trial_id == trials.c.id).where(trials.c.run_id == run['id'])).mappings():
            status = 'pending' if execution['status'] == 'pending' else 'done'
            if execution['status'] == 'invoking':
                conn.execute(executions.update().where(executions.c.id == execution['id']).values(status='outcome_unknown', error={'code': 'LEGACY_INVOCATION_UNCONFIRMED'}))
                status = 'blocked'
            unresolved = unresolved or status == 'pending'
            conn.execute(items.insert().values(id=str(uuid4()), created_at=datetime.now(timezone.utc), project_id=run['project_id'],
                run_id=run['id'], kind='execute', target_id=execution['id'], status=status, epoch=0, lease_until=0,
                next_delivery=0, delivery_count=0))
        batch = conn.execute(sa.select(batches).where(batches.c.run_id == run['id'], batches.c.revision == 0)).mappings().first()
        if batch and batch['status'] == 'completed':
            status = 'cancelled' if run['cancel_requested'] else 'completed'
        elif unresolved:
            status = 'queued'
        else:
            status = 'evaluating'
            if batch:
                conn.execute(items.insert().values(id=str(uuid4()), created_at=datetime.now(timezone.utc), project_id=run['project_id'],
                    run_id=run['id'], kind='grade', target_id=batch['id'], status='pending', epoch=0, lease_until=0,
                    next_delivery=0, delivery_count=0))
        conn.execute(runs.update().where(runs.c.id == run['id']).values(status=status))
        conn.execute(audits.insert().values(id=str(uuid4()), created_at=datetime.now(timezone.utc), run_id=run['id'],
            action='MIGRATED_LEGACY_WORK', detail={'previous_status': run['status']}))

